// Bundles the worker (scripts/worker.mjs plus everything it imports from lib/
// — TypeScript, the "@/…" alias) into ESM that plain `node` runs.
//
//   node scripts/build-worker-bundle.mjs   → dist/worker/worker.mjs
//
// npm packages stay external (packages: "external"): the runtime image brings
// node_modules, own code goes into the bundle. Next is never part of it — the
// worker test (scripts/build-worker-bundle.test.ts) fails if app/ or next/*
// sneaks in.
import { build } from "esbuild";
import { rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export const WORKER_DIST = "dist/worker";

export const WORKER_ENTRIES = {
  worker: "scripts/worker.mjs",
};

/** @param {{ outdir?: string, write?: boolean }} [opts] */
export async function buildWorkerBundle({
  outdir = WORKER_DIST,
  write = true,
} = {}) {
  if (write) await rm(join(root, outdir), { recursive: true, force: true });
  return build({
    absWorkingDir: root,
    entryPoints: WORKER_ENTRIES,
    outdir,
    outExtension: { ".js": ".mjs" },
    write,
    metafile: true,
    bundle: true,
    splitting: true,
    packages: "external",
    platform: "node",
    format: "esm",
    target: "node24",
    tsconfig: "tsconfig.json",
    // Stack traces point at the sources; run with --enable-source-maps.
    sourcemap: true,
    sourcesContent: false,
    logLevel: "warning",
    banner: {
      js: "// Generated by scripts/build-worker-bundle.mjs — do not edit.",
    },
  });
}

if (import.meta.main) {
  await buildWorkerBundle();
  console.log(`[build-worker-bundle] ${WORKER_DIST}/`);
}
